/**
 * Facts about each benchmark that its results cannot tell us: whether the scored test set is public, when it was released, how
 * answers are graded and who runs the models. Researched from each publisher's own pages (first pass 2026-11-19, two cheap agents per
 * benchmark: one to find the fact with a source, one to check it against the source) and corrected by hand since. The quality score
 * reads them (`src/onboarding/quality.ts`). A sub-board inherits its main board's facts (`factsOf`).
 *
 * `test`: "public" when anyone can download the scored tasks with answers or graders (a model may have trained on them); "partial" when
 * some of the scored set is held back (a private test split, hidden answers, a held-out subset); "private" when none of it is published
 * beyond a few examples, or there is no fixed set at all (arena votes). Absent means unknown, which scores neutral.
 */
import type { Benchmark } from "./types";
export type TestSet = "public" | "partial" | "private";
/** "human-judge" is a panel (hired raters, experts, several people); "author-judge" is one person grading by hand, usually the benchmark's author. */
export type Grading = "automatic" | "llm-judge" | "human-judge" | "author-judge" | "human-votes" | "mixed";
export interface BenchmarkFacts {
  test?: TestSet;
  /** One plain sentence: what is public and what is hidden. */
  testNote?: string;
  /** The page that says so. */
  testUrl?: string;
  /** Questions are replaced or added on a schedule, so yesterday's public questions are not tomorrow's test. */
  refreshed?: true;
  /** First public release of this version, YYYY-MM-DD or YYYY-MM. `RELEASES` in quality.ts (hand-verified) wins over this. */
  released?: string;
  grading?: Grading;
  /** One plain sentence on how answers are scored, shown in place of the generic wording when "mixed" or "automatic" would mislead. */
  gradingNote?: string;
  /** Labs report their own scores instead of the publisher running every model. */
  selfReported?: true;
}

export const FACTS_CHECKED = "2026-11-19";

